		if err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to get attachment reader").Wrap(err)
		}
		defer reader.Close()
		return c.Stream(http.StatusOK, contentType, reader)
	default:
		return c.Blob(http.StatusOK, contentType, attachment.Blob)
	}
}

